package com.universe.school.service; import org.springframework.stereotype.Service; import java.time.Instant; import java.util.Map; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; @Service public class SchoolVerificationCodeService {private record Entry(String code,Instant expiresAt){} private final Map<Long,Entry> store=new ConcurrentHashMap<>(); public String issue(Long verificationId){String code=String.valueOf((int)(Math.random()*900000)+100000); store.put(verificationId,new Entry(code,Instant.now().plusSeconds(300))); return code;} public boolean matches(Long id,String code){Entry e=store.get(id); if(e==null)return false; if(Instant.now().isAfter(e.expiresAt())){store.remove(id);return false;} return e.code().equals(code);} public void remove(Long id){store.remove(id);}}
